import React from 'react';

const SignupVisual = () => {
    return (
        <div className="relative flex flex-col justify-end p-6 md:p-8 overflow-hidden bg-primary-container min-w-0 h-full">
            <div className="absolute inset-0 opacity-40">
                <img 
                    alt="Enterprise environment" 
                    className="w-full h-full object-cover mix-blend-overlay"
                    src="https://lh3.googleusercontent.com/aida-public/AB6AXuCRAE9EjTILC5RU9UCaghGHXgZBFWsR1bCfE9XL4un_VF6KGCeoptArTLBEe8_fTLopRRa-CRgSNUUbrxfRX2g9M11HozJX3RYH5_0gbKOskKgdipzWU7UfngnEYUthSXRpmn03YbP3eUHNsnOOzn2KMPjEDqh-pf-Dp4-f6idKUvD_gK7a52unugOJwliWGfHaVdl3ZvyUBR9sTSaEUPwA_ydoTzWYVWtW9QChP9bW6y28kSEgwJvznI-Om3IqaE0A0lRkDEQRzkM"
                />
            </div>
            <div className="relative z-10 min-w-0">
                <h1 className="font-display-sm md:font-display-lg text-display-sm md:text-display-lg text-white mb-2 break-words">Precision at scale.</h1>
                <p className="font-body-sm md:font-body-md text-body-sm md:text-body-md text-on-primary-container max-w-md break-words">Join thousands of professional operators who trust Enterprise Core for high-stakes data integrity and secure infrastructure.</p>
                <div className="mt-4 md:mt-6 flex gap-4">
                    <div className="flex items-center gap-2 px-4 py-2 bg-white/10 backdrop-blur-md rounded-full border border-white/20">
                        <span className="material-symbols-outlined text-white text-[20px]" data-icon="verified_user">verified_user</span>
                        <span className="font-label-md text-label-md text-white">ISO 27001 Certified</span>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default SignupVisual;
